        p, n = (a[0][af[1]], b[2][bf[1]])
        if vertex(a, af[1], scale(n, -1), tol) < 0:
            return None
        w = sub(p, b[0][b[1][bf[1]][0]])
        projection = sub(p, scale(n, dot(n, w) / dot(n, n)))
