        return None if record is None else (tuple((-x for x in record[0])), record[1], record[2])
    ea, eb = (af[1:], bf[1:])
    u, v = (sub(a[0][ea[1]], a[0][ea[0]]), sub(b[0][eb[1]], b[0][eb[0]]))
    aa, ab, bb = (dot(u, u), dot(u, v), dot(v, v))
    det = aa * bb - ab * ab
    if not det:
        return None

